assert len(items)==60,len(items)
def esc(s): return "`"+s.replace("\\","\\\\").replace("`","\\`")+"`"
def sol(ans,va,vb,shown):
    names={'A':'в колонке A значение больше','B':'в колонке B значение больше','C':'значения равны','D':'информации недостаточно'}
    namek={'A':'A бағанындағы мән үлкен','B':'B бағанындағы мән үлкен','C':'мәндер тең','D':'ақпарат жеткіліксіз'}
    fmt=lambda v: (str(round(float(v),4)).rstrip('0').rstrip('.') if not isinstance(v,str) else v)
    if shown: return (f"A: {shown[0]}; B: {shown[1]}. Ответ {ans}: {names[ans]}.",f"A: {shown[0]}; B: {shown[1]}. Жауап {ans}: {namek[ans]}.")
    if ans=='D' : return (f"Значения зависят от неизвестных величин, поэтому однозначно сравнить нельзя. Ответ D.",f"Мәндер белгісіз шамаларға тәуелді, сондықтан нақты салыстыруға болмайды. Жауап D.")
    return (f"A = {fmt(va)}, B = {fmt(vb)}. Ответ {ans}: {names[ans]}.",f"A = {fmt(va)}, B = {fmt(vb)}. Жауап {ans}: {namek[ans]}.")
out=["import { QT } from \"./kit\";","","/** Тест 1 · Количественные характеристики (60). Переписано: числа изменены, ответы вычислены кодом (gen_quant.py), разбор ru/kk. */","export const T01_QUANT = ["]
for i,(ra,ka,rb,kb,va,vb,ans,common,shown) in enumerate(items,1):
    a=ans or cm(va,vb)
    sr,sk=sol(a,va,vb,shown)
    c=f"{esc(common[0])}, {esc(common[1])}" if common else "undefined, undefined"
    out.append(f"  QT({i}, {esc(ra)}, {esc(ka)}, {esc(rb)}, {esc(kb)}, \"{a}\", {esc(sr)}, {esc(sk)}, {c}),")
out.append("];")
print("\n".join(out))
sys.stderr.write(''.join((ans or cm(va,vb)) for (_,_,_,_,va,vb,ans,_,_) in items)+"\n")
